import operator
from typing import Annotated, TypedDict
from langgraph.graph import StateGraph, START, END

class Finding(TypedDict):
    agent: str
    source: str
    text: str

class Board(TypedDict):
    awb: str
    findings: Annotated[list[Finding], operator.add]   # append, never replace
    decision: str

def carrier(s: Board):
    return {"findings": [{"agent": "carrier", "source": "carrier API",
                          "text": "Linehaul delayed 18 h at Nagpur hub"}]}

def warehouse(s: Board):
    return {"findings": [{"agent": "warehouse", "source": "WMS",
                          "text": "Packed, awaiting pickup"}]}

def weather(s: Board):
    return {"findings": [{"agent": "weather", "source": "IMD alert",
                          "text": "Heavy rain warning, Vidarbha"}]}

def dispatcher(s: Board):
    risky = [f for f in s["findings"] if f["agent"] in ("carrier", "weather")]
    return {"decision": "reroute via Hyderabad" if len(risky) >= 2 else "hold"}

g = StateGraph(Board)
for name, fn in [("carrier", carrier), ("warehouse", warehouse),
                 ("weather", weather), ("dispatcher", dispatcher)]:
    g.add_node(name, fn)
for name in ("carrier", "warehouse", "weather"):
    g.add_edge(START, name)                      # fan out in parallel
g.add_edge(["carrier", "warehouse", "weather"], "dispatcher")   # join
g.add_edge("dispatcher", END)
print(g.compile().invoke({"awb": "BLR123", "findings": []}))

